import{_ as o,o as t,c as i,a2 as r}from"./chunks/framework.CiQ1TEvV.js";const h=JSON.parse('{"title":"Query Decomposition","description":"","frontmatter":{},"headers":[],"relativePath":"features/query-decomposition.md","filePath":"features/query-decomposition.md","lastUpdated":1785115728000}'),n={name:"features/query-decomposition.md"};function a(s,e,l,u,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="query-decomposition" tabindex="-1">Query Decomposition <a class="header-anchor" href="#query-decomposition" aria-label="Permalink to &quot;Query Decomposition&quot;">​</a></h1><p>Complex questions are split into sub-queries and retrieved concurrently, then the results are fused into a single comprehensive answer.</p><h2 id="why-decompose" tabindex="-1">Why Decompose? <a class="header-anchor" href="#why-decompose" aria-label="Permalink to &quot;Why Decompose?&quot;">​</a></h2><p>A question like &quot;Compare the findings of the 2023 and 2024 reports on renewable energy&quot; requires:</p><ol><li>Finding the 2023 report&#39;s findings</li><li>Finding the 2024 report&#39;s findings</li><li>Comparing them</li></ol><p>A single retrieval query would likely miss one of the reports or dilute the relevance signal. Decomposition ensures each sub-question gets its own focused retrieval.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><strong>Analysis</strong>: The LLM analyzes the original question and breaks it into atomic sub-queries</li><li><strong>Concurrent Retrieval</strong>: Each sub-query is dispatched to the retrieval pipeline in parallel via <code>ThreadPoolExecutor</code></li><li><strong>Result Fusion</strong>: Results from all sub-queries are deduplicated by chunk and scored</li><li><strong>Context Assembly</strong>: A single combined context is built and sent to the LLM for the final answer</li></ol><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><ul><li>Sub-queries run concurrently, so total latency is close to the slowest individual query rather than the sum</li><li>Chunk deduplication prevents the same document from being counted multiple times</li><li>Dynamic Top-K is applied to the fused result set</li></ul><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><p>Query decomposition is automatically used in both:</p><ul><li><strong>Standard RAG</strong> pipeline (<code>answer_query</code>)</li><li><strong>Graph RAG</strong> pipeline (<code>graph_rag_pipeline</code>)</li></ul><p>There is no separate user-facing switch; Mneme decides whether a query is complex enough to benefit from decomposition based on its structure.</p>',14)])])}const m=o(n,[["render",a]]);export{h as __pageData,m as default};
